const BOSS_REPLY_ERRORS = {
  missingQuestion: "needsBossReply outcome missing 'question' field",
  unregisteredState: (stateId: string) =>
    `state ${stateId} declared needsBossReply but is not registered as resumable`,
} as const;

// Required-payload fields whose value is the player's verbatim long-form
// prose. The runtime carries `finalText.trim()` into these fields rather
// than asking the judge to round-trip the text through JSON. Short
// extracted fields (`question`, `taskDescription`, `irNumber`, …) stay
// judge-extracted — they are not in this set.
const VERBATIM_PAYLOAD_FIELDS: ReadonlySet<string> = new Set([
  'reviews',
  'challenges',
]);

// Normalize an unknown error value to the compact `{ name, message }`
// shape used by Captain-pane / status emissions. Returns `undefined`
// for nullish input so callers can omit absent errors.
function normalizeErrorCompact(
  err: unknown,
): { name: string; message: string } | undefined {
  if (err === undefined || err === null) return undefined;
  if (err instanceof Error) {
    return { name: err.name, message: err.message };
  }
  if (typeof err === 'object') {
    const o = err as Record<string, unknown>;
    if (typeof o.message === 'string') {
      return {
        name: typeof o.name === 'string' ? o.name : 'Error',
        message: o.message,
      };
    }
  }
  return { name: 'Error', message: String(err) };
}

// Normalize an unknown error value to the full `{ name, message, stack }`
// shape used by telemetry emissions. Returns `undefined` for nullish
// input. `stack` is omitted when not available on the source value.
function normalizeErrorFull(
  err: unknown,
): { name: string; message: string; stack?: string } | undefined {
  const compact = normalizeErrorCompact(err);
  if (compact === undefined) return undefined;
  if (err instanceof Error) {
    return err.stack !== undefined ? { ...compact, stack: err.stack } : compact;
  }
  if (typeof err === 'object' && err !== null) {
    const stack = (err as Record<string, unknown>).stack;
    if (typeof stack === 'string') {
      return { ...compact, stack };
    }
  }
  return compact;
}

// Normalize any `error` field inside a telemetry event so failed
// transitions don't leak raw Error instances through the channel.
function normalizeEventForTelemetry(event: unknown): unknown {
  return normalizeJsonSafe(event, new WeakSet<object>(), false);
}

function normalizeJsonSafe(
  value: unknown,
  seen: WeakSet<object>,
  arrayItem: boolean,
): unknown {
  if (value === undefined) return arrayItem ? null : undefined;
  if (value === null || typeof value === 'string' || typeof value === 'boolean') {
    return value;
  }
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'symbol' || typeof value === 'function') {
    return arrayItem ? null : undefined;
  }
  if (value instanceof Error) return normalizeErrorFull(value);
  if (value instanceof Date) return value.toISOString();
  if (seen.has(value)) return '[Circular]';
  seen.add(value);
  if (Array.isArray(value)) {
    const normalized = value.map((item) => normalizeJsonSafe(item, seen, true));
    seen.delete(value);
    return normalized;
  }
  const normalized: Record<string, unknown> = {};
  for (const [key, item] of Object.entries(value)) {
    const next =
      key === 'error'
        ? normalizeErrorFull(item)
        : normalizeJsonSafe(item, seen, false);
    if (next !== undefined) normalized[key] = next;
  }
  seen.delete(value);
  return normalized;
}

// Internal capabilities (DR-004 §10). Each ships with its final
// signature; behavior lands in the per-capability task noted by the
// TODO marker.

// Player-prompt composer — DR-004 §6.
// Substitutes the three placeholder tokens in `input.prompt` (literal
// string replace, no escaping) and arranges labelled blocks around
// the prompt body. Context blocks the body refers to as prior
// material (`Boss intent:`, `Task description:`) are prepended;
// action blocks the body refers to as material below
// (`Review items:`, `Rebuttals:`) are appended after the body so the
// CODE-N prompts' "review item below" / "rebuttal below" phrasing
// matches the rendered layout. When a state resumes from a Boss
// reply, the continuation preamble and Q/A blocks precede every
// ordinary block. The FSM's prompt body is never re-flowed.

function composePlayerPrompt(input: CaptainInput): string {
  const blocks: string[] = [];
  if (
    input.pendingBossQuestion !== undefined &&
    input.bossReply !== undefined
  ) {
    blocks.push(
      'You previously paused this task to ask Boss a question; Boss has now replied. Continue the same task using the reply below.',
    );
    blocks.push(`Boss question:\n${input.pendingBossQuestion.question}`);
    blocks.push(`Boss reply:\n${input.bossReply}`);
  }
  if (input.intent !== undefined) {
    blocks.push(`Boss intent:\n${input.intent}`);
  }
  if (input.taskDescription !== undefined) {
    blocks.push(`Task description:\n${input.taskDescription}`);
  }

  let body = input.prompt;
  if (input.irNumber !== undefined) {
    body = body.replaceAll('<#>', input.irNumber);
  }
  if (input.coderPlayer !== undefined) {
    body = body.replaceAll('<coder-llm>', input.coderPlayer);
  }
  if (input.reviewerPlayer !== undefined) {
    body = body.replaceAll('<reviewer-llm>', input.reviewerPlayer);
  }

  blocks.push(body);

  if (input.reviews !== undefined) {
    blocks.push(`Review items:\n${input.reviews}`);
  }
  if (input.challenges !== undefined) {
    blocks.push(`Rebuttals:\n${input.challenges}`);
  }

  return blocks.join('\n\n');
}

// Player-id resolver — DR-004 §2 / PBRT-8.
// Non-composite: Coder→'coder', Reviewer→'reviewer'. The composite
// Committer (= Coder | Reviewer per code.gears.md) resolves to the
// configured alias when present: `input.committerPlayer`, the
// validated `captain.options.playbooks.code.options.committer`
// (PBRT-8 / PBRT-30), already a baked player id ('coder' / 'reviewer').
// Absent a
// configured alias it falls back to the DR-004 §2 baked binding by
// populated <playerName>Player field: prefer `coderPlayer` (CODE-18
// wires only coderPlayer; CODE-19 wires both so coderPlayer still wins
// as the alias's first alternative), fall back to `reviewerPlayer`
// only if a future gear ships a reviewer-only Committer item, and
// finally to the alias's first alternative (Coder) when neither is
// set. The alias selects only the host pane; it is not a PBRT-4
// identity string, so it leaves <coder-llm> / <reviewer-llm>
// untouched and `input.player` stays `Committer` (PLAYBOOK-3).
function resolvePlayerId(input: CaptainInput): string {
  switch (input.player) {
    case 'Coder':
      return 'coder';
    case 'Reviewer':
      return 'reviewer';
    case 'Committer':
      if (input.committerPlayer !== undefined) return input.committerPlayer;
      if (input.coderPlayer !== undefined) return 'coder';
      if (input.reviewerPlayer !== undefined) return 'reviewer';
      return 'coder';
    default: {
      const exhaustive: never = input.player;
      throw new Error(
        `resolvePlayerId: unknown player ${String(exhaustive)}`,
      );
    }
  }
}

type JudgePurpose =
  | 'boss-input-classification'
  | 'player-output-adjudication';

interface RuntimeBoundaryCalls {
  callPlayer(
    input: CaptainInput,
    playerId: string,
    prompt: string,
    signal: AbortSignal,
  ): Promise<PlayerResult>;
  callJudge(
    purpose: JudgePurpose,
    stateId: string | undefined,
    prompt: string,
    signal: AbortSignal,
  ): Promise<string>;
}

// LLM judge — DR-004 §4. Builds a prompt that lists each declared
// outcome verbatim, asks ports.callJudge for a JSON
// `{ guard, …payloadFields }` response, and returns the parsed
// object once the chosen guard is one of the input.result keys.
// Adjudicator failures (malformed JSON, missing/unknown guard) are
// control-plane errors and propagate via throw per slc/link.md.
async function adjudicate(
  input: CaptainInput,
  finalText: string,
  ports: PlaybookPorts,
  signal: AbortSignal,
  boundary?: RuntimeBoundaryCalls,
): Promise<CaptainOutput> {
  const prompt = buildJudgePrompt(input, finalText);
  const raw = boundary
    ? await boundary.callJudge(
        'player-output-adjudication',
        stateIdBySourceItem.get(input.sourceItem),
        prompt,
        signal,
      )
    : await ports.callJudge(prompt, signal);
  const parsed = parseJudgeJson(raw);
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new Error('adjudicate: judge response is not a JSON object');
  }
  const obj = parsed as Record<string, unknown>;
  const guard = obj.guard;
  if (typeof guard !== 'string') {
    throw new Error('adjudicate: judge response missing string "guard" field');
  }
  if (!Object.prototype.hasOwnProperty.call(input.result, guard)) {
    throw new Error(
      `adjudicate: unknown guard "${guard}" — declared guards: ${Object.keys(
        input.result,
      ).join(', ')}`,
    );
  }
  // Per slc/link.md, a missing payload field the state's `result`
  // description requires is a control-plane error. The FSM names
  // required fields with the literal phrase
  //   Output shall include `<fieldName>: <...>`
  // so we extract those tokens and require each to be a string in
  // the judge response — except for VERBATIM_PAYLOAD_FIELDS
  // (`reviews`, `challenges`), where the runtime substitutes
  // `finalText.trim()` so the long-form prose is not round-tripped
  // through judge JSON. Short extracted fields like `question` and
  // `taskDescription` keep the existing extract-and-validate path.
  const verbatim = finalText.trim();
  for (const field of extractRequiredFields(input.result[guard])) {
    if (VERBATIM_PAYLOAD_FIELDS.has(field)) {
      obj[field] = verbatim;
      continue;
    }
    if (typeof obj[field] !== 'string') {
      if (guard === 'needsBossReply' && field === 'question') {
        throw new Error(BOSS_REPLY_ERRORS.missingQuestion);
      }
      throw new Error(
        `adjudicate: judge response missing required field "${field}" for guard "${guard}"`,
      );
    }
  }
  return obj as CaptainOutput;
}

function extractRequiredFields(description: string): string[] {
  const fields: string[] = [];
  const re = /Output shall include `([A-Za-z_][A-Za-z0-9_]*):/g;
  for (const m of description.matchAll(re)) {
    fields.push(m[1]);
  }
  return fields;
}

function buildJudgePrompt(input: CaptainInput, finalText: string): string {
  const lines: string[] = [];
  lines.push(`The ${input.player} just produced this output:`);
  lines.push('');
  lines.push('```');
  lines.push(finalText);
  lines.push('```');
  lines.push('');
  lines.push(
    'Pick exactly one outcome by `guard` and return JSON ' +
      '`{ guard, …payloadFields }`. Required payload fields are ' +
      'named in the outcome description. Do not copy long-form ' +
      'verbatim fields (`reviews`, `challenges`) — the runtime ' +
      "carries the player's output into those fields verbatim, " +
      'so any value you supply for them will be overwritten.',
  );
  lines.push('');
  for (const [key, description] of Object.entries(input.result)) {
    lines.push(`- \`${key}\` — ${description}`);
  }
  return lines.join('\n');
}

// Judge replies are meant to be a single JSON object, but LLMs
// routinely wrap them in prose ("Here is the result: …"), Markdown
// code fences, or trailing commentary, and occasionally emit a
// trailing comma or truncate the tail (a dropped closing brace, an
// unterminated string). parseJudgeJson is deliberately lenient: it
// first tries a strict parse of the (optionally fenced) body, then
// scans every `{`/`[` as a possible start in document order and
// returns the first recoverable object. At each start it prefers a
// strict balanced span and falls back to a repaired (trailing-comma /
// truncation) span, so a damaged object earlier in the prose is not
// overridden by a cleaner one later. Scanning every start (not just
// the first bracket) keeps a bracketed fragment in surrounding prose —
// e.g. an aside like `see [1]` or `{n/a}` before the real object —
// from masking a later, genuinely valid object. Both callers
// (classification and adjudication) expect an object, so plain objects
// win over arrays/scalars; the first value of any shape is remembered
// so a legitimately array/scalar reply still surfaces to the caller's
// own object check. Only a reply from which no JSON value can be
// recovered is treated as malformed and throws, preserving the
// control-plane error contract (PBRT-7, PBRT-10).
function parseJudgeJson(raw: string): unknown {
  const fenced = stripCodeFence(raw.trim());
  // Fast path: a well-formed (optionally fenced) JSON body.
  try {
    return JSON.parse(fenced);
  } catch {
    // Fall through to lenient extraction + repair.
  }
  const starts: number[] = [];
  for (let i = 0; i < fenced.length; i++) {
    const ch = fenced[i];
    if (ch === '{' || ch === '[') starts.push(i);
  }
  // Walk starts in document order. At each start prefer a strict
  // balanced span (most trustworthy) and fall back to a repaired one
  // for a trailing-comma / truncated tail, so the earliest intended
  // object wins even when it needs repair. Return the first plain
  // object; remember the first value of any shape so a legitimately
  // array/scalar reply still surfaces to the caller's own object check.
  let firstValue: { value: unknown } | undefined;
  for (const start of starts) {
    let parsedHere: { value: unknown } | undefined;
    for (const repair of [false, true]) {
      const candidate = extractJsonValue(fenced, start, repair);
      if (candidate === undefined) continue;
      try {
        parsedHere = { value: JSON.parse(candidate) };
      } catch {
        continue; // not parseable this way — try repair, then next start
      }
      break; // prefer the strict span at this start over its repair
    }
    if (parsedHere === undefined) continue;
    if (isPlainObject(parsedHere.value)) return parsedHere.value;
    if (firstValue === undefined) firstValue = parsedHere;
  }
  if (firstValue !== undefined) return firstValue.value;
  throw new Error('adjudicate: judge response is not valid JSON');
}

function isPlainObject(value: unknown): boolean {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// Strip a single Markdown code fence that wraps the whole string.
function stripCodeFence(text: string): string {
  const fence = text.match(/^```(?:json)?\s*\n?([\s\S]*?)\n?```$/);
  return fence ? fence[1].trim() : text;
}

// Scan from `start` (a `{`/`[` index), tracking string and
// bracket-nesting state, and emit the balanced JSON value rooted
// there. Anything after the top-level value closes is ignored (so a
// trailing code fence or commentary does not matter). With
// `repair === false` the span is returned only if it actually closes,
// and trailing commas are left intact — so the caller can prefer a
// cleanly-balanced span before attempting repair; if input ends
// before the value closes, undefined is returned. With
// `repair === true` common damage is fixed: a trailing comma before a
// close is removed, an unterminated string is closed, and any
// brackets still open at end-of-input are closed in order.
function extractJsonValue(
  text: string,
  start: number,
  repair: boolean,
): string | undefined {
  const stack: string[] = [];
  let out = '';
  let inString = false;
  let escaped = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      out += ch;
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') {
      inString = true;
      out += ch;
      continue;
    }
    if (ch === '{' || ch === '[') {
      stack.push(ch === '{' ? '}' : ']');
      out += ch;
      continue;
    }
    if (ch === '}' || ch === ']') {
      if (repair) out = dropTrailingComma(out);
      out += ch;
      stack.pop();
      if (stack.length === 0) return out; // top-level value complete
      continue;
    }
    out += ch;
  }
  // End of input before the top-level value closed.
  if (!repair) return undefined; // strict pass: no balanced span here
  if (inString) out += '"';
  out = dropTrailingComma(out);
  while (stack.length > 0) out += stack.pop();
  return out;
}

// Remove a trailing comma (and any whitespace after it) at the end of
// the accumulated output, so `{"a":1,}` / `[1,2,]` and truncated
// `{"a":1,` repair to valid JSON.
function dropTrailingComma(out: string): string {
  return out.replace(/,(\s*)$/, '$1');
}

// Boss-event classifier — DR-004 §3.
// Every non-empty Boss turn goes through ports.callJudge. Slash-prefixed
// text is ordinary content once a host has routed the turn to this
// playbook; `/command` selection belongs outside handleBossInput. The
// classifier is state-aware so awaitBossReply can distinguish a direct
// answer (BOSS_REPLY) from a fresh directive that abandons the pending
// question through the FSM's existing transitions.
async function classifyBossText(
  text: string,
  ports: PlaybookPorts,
  signal: AbortSignal,
  snapshotOrState?: unknown,
  boundary?: RuntimeBoundaryCalls,
): Promise<CodingEvent | undefined> {
  const trimmed = text.trim();
  if (trimmed === '') return undefined;

  return classifyWithLlm(text, ports, signal, snapshotOrState, boundary);
}

// JumpableStateId is internal to code.fsm.ts (not exported), so
// recover it from the CodingEvent union for typed casts here.
type JumpableStateId = Extract<
  CodingEvent,
  { type: 'BOSS_INTERRUPT' }
>['targetId'];

const rootEvents = enumerateRootEvents(codingMachine);
const bossInterruptTargets = rootEvents.bossInterruptTargetDescriptions;
const bossInterruptTargetIds: ReadonlySet<string> = new Set(
  bossInterruptTargets.map((target) => target.stateId),
);

async function classifyWithLlm(
  text: string,
  ports: PlaybookPorts,
  signal: AbortSignal,
  snapshotOrState?: unknown,
  boundary?: RuntimeBoundaryCalls,
): Promise<CodingEvent | undefined> {
  const state = classifierState(snapshotOrState);
  const prompt = buildClassifierPrompt(text, state);
  const stateId = typeof state.value === 'string' ? state.value : undefined;
  const raw = boundary
    ? await boundary.callJudge(
        'boss-input-classification',
        stateId,
        prompt,
        signal,
      )
    : await ports.callJudge(prompt, signal);
  let parsed: unknown;
  try {
    parsed = parseJudgeJson(raw);
  } catch {
    // No JSON value could be recovered. Classification failures are
    // non-fatal — unlike adjudication, which throws to the failure
    // state (PBRT-10) — so surface one status and take no FSM action,
    // consistent with the other invalid-reply paths below (PBRT-7).
    await ports.emitStatus('Classifier reply was not recoverable JSON');
    return undefined;
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    await ports.emitStatus('Classifier returned a non-object JSON response');
    return undefined;
  }
  const obj = parsed as Record<string, unknown>;
  const eventType = obj.event;
  if (typeof eventType !== 'string') {
    await ports.emitStatus('Classifier did not name an event type');
    return undefined;
  }
  const payload =
    typeof obj.payload === 'object' &&
    obj.payload !== null &&
    !Array.isArray(obj.payload)
      ? (obj.payload as Record<string, unknown>)
      : {};

  switch (eventType) {
    case 'NO_ACTION':
    case 'NO_FSM_ACTION':
    case 'NONE':
      return undefined;
    case 'START_CODING': {
      if (typeof payload.intent !== 'string') {
        await ports.emitStatus('Classifier omitted intent for START_CODING');
        return undefined;
      }
      return { type: 'START_CODING', intent: payload.intent };
    }
    case 'CONTINUE_IR': {
      if (typeof payload.irNumber !== 'string') {
        await ports.emitStatus('Classifier omitted irNumber for CONTINUE_IR');
        return undefined;
      }
      return { type: 'CONTINUE_IR', irNumber: payload.irNumber };
    }
    case 'SUMMARIZE_IR': {
      if (typeof payload.irNumber !== 'string') {
        await ports.emitStatus('Classifier omitted irNumber for SUMMARIZE_IR');
        return undefined;
      }
      return { type: 'SUMMARIZE_IR', irNumber: payload.irNumber };
    }
    case 'BOSS_INTERRUPT': {
      if (typeof payload.targetId !== 'string') {
        await ports.emitStatus(
          'Classifier omitted targetId for BOSS_INTERRUPT',
        );
        return undefined;
      }
      if (!bossInterruptTargetIds.has(payload.targetId)) {
        await ports.emitStatus(
          `Classifier supplied invalid targetId for BOSS_INTERRUPT: ${payload.targetId}`,
        );
        return undefined;
      }
      return {
        type: 'BOSS_INTERRUPT',
        targetId: payload.targetId as JumpableStateId,
        ...(typeof payload.intent === 'string'
          ? { intent: payload.intent }
          : {}),
        ...(typeof payload.irNumber === 'string'
          ? { irNumber: payload.irNumber }
          : {}),
      };
    }
    case 'BOSS_REPLY': {
      if (state.value !== 'awaitBossReply') {
        await ports.emitStatus(
          'Classifier returned BOSS_REPLY outside awaitBossReply',
        );
        return undefined;
      }
      if (typeof payload.answer !== 'string') {
        await ports.emitStatus('Classifier omitted answer for BOSS_REPLY');
        return undefined;
      }
      return { type: 'BOSS_REPLY', answer: payload.answer };
    }
    default:
      await ports.emitStatus(
        `Classifier returned unknown event type: ${eventType}`,
      );
      return undefined;
  }
}

interface ClassifierState {
  value: unknown;
  context: Record<string, unknown>;
}

function classifierState(snapshotOrState: unknown): ClassifierState {
  if (
    snapshotOrState !== null &&
    typeof snapshotOrState === 'object' &&
    'value' in snapshotOrState
  ) {
    const candidate = snapshotOrState as {
      value?: unknown;
      context?: unknown;
    };
    return {
      value: candidate.value,
      context:
        candidate.context !== null &&
        typeof candidate.context === 'object' &&
        !Array.isArray(candidate.context)
          ? (candidate.context as Record<string, unknown>)
          : {},
    };
  }
  return { value: snapshotOrState, context: {} };
}

function buildClassifierPrompt(text: string, state: ClassifierState): string {
  const currentState =
    typeof state.value === 'string' ? state.value : 'unknown';
  const pendingBossQuestion = pendingBossQuestionFromContext(state.context);
  const lines = [
    'Classify the following Boss message into exactly one of these events.',
    'Respond with JSON: { "event": "<TYPE>", "payload": { ...fields } }.',
    'Use { "event": "NO_ACTION", "payload": {} } when no FSM action should be taken.',
    '',
    `Current state: ${currentState}`,
  ];
  if (pendingBossQuestion !== undefined) {
    lines.push(
      `Pending Boss question: ${pendingBossQuestion.question}`,
      `Pending resume state: ${pendingBossQuestion.resumeStateId}`,
    );
  }
  lines.push(
    '',
    'Events:',
    '- START_CODING: payload { intent: "<free-form goal>" }',
    '- CONTINUE_IR: payload { irNumber: "<number>" }',
    '- SUMMARIZE_IR: payload { irNumber: "<number>" }',
    '- BOSS_INTERRUPT: payload { targetId: "<stateId>", intent?: "<free-form goal>", irNumber?: "<number>" }',
    '  targetId must be one of these jumpable states:',
  );
  for (const target of bossInterruptTargets) {
    lines.push(`  - ${target.stateId}: ${target.description}`);
  }
  if (currentState === 'awaitBossReply') {
    lines.push('- BOSS_REPLY: payload { answer: "<verbatim Boss answer>" }');
  } else {
    lines.push('- BOSS_REPLY: valid only when Current state is awaitBossReply');
  }
  lines.push(
    '',
    'Boss message:',
    '```',
    text,
    '```',
  );
  return lines.join('\n');
}

// Captain-actor bridge — DR-004 §7. One PromiseActorLogic that the
// codingMachine invokes from every captain-invoking state. Per turn:
// resolve playerId, compose the player prompt, await
// ports.callPlayer, adjudicate the finalText. PlayerResult status of
// 'aborted' or 'error' throws so XState routes via onError → #failed
// (the single fail-stop sink for both Captain errors and player
// failures).
//
// `getActiveSignal` is the runtime's hook for flowing the Boss's
// `handleBossInput.signal` into the host port calls — fromPromise
// hands the bridge XState's actor-scoped signal, which only fires
// on actor.stop(), not on Boss abort. When omitted (e.g. direct
// captainBridge tests), the bridge falls back to XState's signal.
function captainBridge(
  ports: PlaybookPorts,
  getActiveSignal?: () => AbortSignal | undefined,
  boundary?: RuntimeBoundaryCalls,
) {
  return fromPromise<CaptainOutput, CaptainInput>(
    async ({ input, signal }) => {
      const activeSignal = getActiveSignal?.() ?? signal;
      const playerId = resolvePlayerId(input);
      const prompt = composePlayerPrompt(input);
      const result = boundary
        ? await boundary.callPlayer(input, playerId, prompt, activeSignal)
        : await ports.callPlayer(playerId, prompt, activeSignal, {
            resume: false,
          });
      if (result.status !== 'ok') {
        throw new Error(
          result.error ??
            `captainBridge: callPlayer status "${result.status}"`,
        );
      }
      if (result.finalText === undefined) {
        throw new Error(
          'captainBridge: callPlayer returned status=ok with no finalText',
        );
      }
      const output = await adjudicate(
        input,
        result.finalText,
        ports,
        activeSignal,
        boundary,
      );
      validateBossReplyOutput(input, output);
      return output;
    },
  );
}

// Captain pane display — PBRT-3 / PBRT-14.
// The Captain pane is a stream of three glyphs plus one bare
// captain-speech act, designed so a reader can parse each line at a
// glance:
//   (no glyph)  bare FSM event type — host renders as captain speech
//               (e.g., `captain> START_CODING`)
//   ⤷           captain-invoking state entry: `<Player>: <label>`
//   →           transition guard outcome (`· field=N` tallies
//               appended); the host presenter owns any visual
//               nesting under the preceding ⤷ entry

//   ◆           failure state (with `lastError` data) and the
//               `awaitBossReply` suspension state (custom payload)
// The runtime emits no status line on entry to the idle state
// (`ready`) or the terminal state (`done`); the next `boss>` prompt
// is the implicit "turn over" signal. Prompts and full player output
// ride the player panes; the Captain pane keeps to the state-machine
// shape.

const STATE_LABELS: Readonly<Record<string, string>> = {
  planAndImplement: 'plan & implement',
  respondToReview: 'respond to review',
  continueIr: 'continue IR task',
  summarizeSpecs: 'summarize IR into specs',
  reviewBossCommitSpecs: 'review Boss-intent commit (specs only)',
  reviewBossCommitCode: 'review Boss-intent commit (code only)',
  reviewBossCommitMixed: 'review Boss-intent commit (specs + code)',
  reviewIrTaskCommitSpecs: 'review IR-task commit (specs only)',
  reviewIrTaskCommitCode: 'review IR-task commit (code only)',
  reviewIrTaskCommitMixed: 'review IR-task commit (specs + code)',
  reviewChangesSpecs: 'review uncommitted edits (specs only)',
  reviewChangesCode: 'review uncommitted edits (code only)',
  reviewChangesMixed: 'review uncommitted edits (specs + code)',
  reviewChangesAndChallengesSpecs:
    'review uncommitted edits + rebuttals (specs only)',
  reviewChangesAndChallengesCode:
    'review uncommitted edits + rebuttals (code only)',
  reviewChangesAndChallengesMixed:
    'review uncommitted edits + rebuttals (specs + code)',
  adjudicateChallenges: 'adjudicate rebuttals',
  commitCoderInitial: "commit Coder's initial changes",
  commitJoint: 'commit reviewed changes',
};

interface StateMetadata {
  player: CaptainInput['player'];
  sourceItem: string;
  label: string;
}

const stateMetadata: ReadonlyMap<string, StateMetadata> = (() => {
  const m = new Map<string, StateMetadata>();
  for (const s of enumerateCaptainStates(codingMachine)) {
    const label = STATE_LABELS[s.stateId];
    if (!label) {
      throw new Error(
        `code.playbook.ts: STATE_LABELS missing entry for captain-invoking state '${s.stateId}'`,
      );
    }
    const input = s.getInput({});
    m.set(s.stateId, { player: input.player, sourceItem: s.sourceItem, label });
  }
  return m;
})();

const stateIdBySourceItem: ReadonlyMap<string, string> = new Map(
  [...stateMetadata.entries()].map(([stateId, meta]) => [
    meta.sourceItem,
    stateId,
  ]),
);

const registeredResumableStateIds: ReadonlySet<string> = new Set(
  enumerateAwaitBossReply(codingMachine).bossReplyTransitions.map(
    (transition) => transition.target,
  ),
);

function validateBossReplyOutput(
  input: CaptainInput,
  output: CaptainOutput,
): void {
  if (output.guard !== 'needsBossReply') return;
  if (typeof output.question !== 'string') {
    throw new Error(BOSS_REPLY_ERRORS.missingQuestion);
  }
  const stateId = stateIdBySourceItem.get(input.sourceItem);
  if (stateId === undefined || !registeredResumableStateIds.has(stateId)) {
    throw new Error(
      BOSS_REPLY_ERRORS.unregisteredState(stateId ?? input.sourceItem),
    );
  }
}

const QUIESCENT_STATES: ReadonlySet<string> = new Set([
  'ready',
  'awaitBossReply',
  'done',
  'failed',
]);

// States whose entry the runtime does not surface on the Captain
// pane per PBRT-3: the readline returning to its `boss>` prompt is
// the implicit "turn over" signal, so a `◆ ready` / `◆ done`
// tombstone is redundant.
const SUPPRESSED_ENTRY_STATES: ReadonlySet<string> = new Set([
  'ready',
  'done',
]);

// Captain-pane surface (PBRT-3): every captain-invoking state plus
// the quiescent states whose entry still carries information
// (failure with `lastError`, awaitBossReply with the pending
// question). `ready` and `done` flow through the inspect handler
// but their entries are dropped before emitStatus per
// SUPPRESSED_ENTRY_STATES above.
const CAPTAIN_PANE_STATES: ReadonlySet<string> = new Set([
  ...stateMetadata.keys(),
  ...QUIESCENT_STATES,
]);

interface PendingBossQuestionForStatus {
  resumeStateId: string;
  sourceItem: string;
  player: string;
  question: string;
}

function pendingBossQuestionFromContext(
  context: Record<string, unknown>,
): PendingBossQuestionForStatus | undefined {
  const pending = context.pendingBossQuestion;
  if (pending === undefined || typeof pending !== 'object') {
    return undefined;
  }
  const candidate = pending as Partial<
    Record<keyof PendingBossQuestionForStatus, unknown>
  >;
  if (
    typeof candidate.resumeStateId !== 'string' ||
    typeof candidate.sourceItem !== 'string' ||
    typeof candidate.player !== 'string' ||
    typeof candidate.question !== 'string'
  ) {
    return undefined;
  }
  return {
    resumeStateId: candidate.resumeStateId,
    sourceItem: candidate.sourceItem,
    player: candidate.player,
    question: candidate.question,
  };
}

// PBRT-3 / PBRT-14: on entry to `awaitBossReply` the runtime surfaces
// the pending player question as a captain-speech act attributed to the
// asking player (`<player> asks: <full question>`), emitted with no
// glyph so the host renders it as captain speech. The question is
// carried verbatim and in full — the judge JSON that produced it rides
// a hidden callCaptain (PBRT-15), so this line is the Boss's only
// legible view of what was asked.
function formatAwaitBossReplyQuestion(
  context: Record<string, unknown>,
): string {
  const pending = pendingBossQuestionFromContext(context);
  const player = pending?.player ?? 'unknown';
  const question = pending?.question ?? '';
  return `${player} asks: ${question}`;
}

// The rider-less routing marker emitted right after the question line.
// It carries only the resume target, asking player, and source item;
// the former `q="<first 80 chars>"` excerpt rider is dropped now that
// the full question rides the captain-speech line above.
function formatAwaitBossReplyMarker(
  context: Record<string, unknown>,
): string {
  const pending = pendingBossQuestionFromContext(context);
  const resumeStateId = pending?.resumeStateId ?? 'unknown';
  const player = pending?.player ?? 'unknown';
  const sourceItem = pending?.sourceItem ?? 'unknown';
  return `◆ awaiting Boss reply · ${resumeStateId} · ${player} · ${sourceItem}`;
}

function formatStateEntry(stateId: string): string | undefined {
  if (SUPPRESSED_ENTRY_STATES.has(stateId)) return undefined;
  if (stateId === 'failed') return '◆ failed';
  const meta = stateMetadata.get(stateId);
  if (!meta) return `⤷ ${stateId}`;
  return `⤷ ${meta.player}: ${meta.label}`;
}

function formatTransition(event: unknown): string | undefined {
  const output = (event as { output?: Record<string, unknown> })?.output;
  if (!output || typeof output.guard !== 'string') return undefined;
  const tallies: string[] = [];
  for (const field of ['reviews', 'challenges'] as const) {
    const value = output[field];
    if (typeof value === 'string' && value.trim().length > 0) {
      const items = value.match(/^\s*\d+\.\s/gm);
      tallies.push(`${field}=${items ? items.length : 1}`);
    }
  }
  const suffix = tallies.length > 0 ? ` · ${tallies.join(' · ')}` : '';
  // No leading whitespace: visual nesting under the preceding ⤷
  // entry is the host presenter's concern (cligent's writeStatusLine
  // emits status messages verbatim, with its own chrome but no
  // continuation indent; layout is its job, not ours).
  return `→ ${output.guard}${suffix}`;
}

function formatClassification(eventType: string): string {
  return eventType;
}

function stateTelemetryPayload(
  from: unknown,
  to: string,
  event: unknown,
  context: Record<string, unknown>,
): Record<string, unknown> {
  const payload: Record<string, unknown> = {
    from: from ?? null,
    to,
    event: normalizeEventForTelemetry(event) ?? null,
  };
  if (to === 'awaitBossReply') {
    const pendingBossQuestion = pendingBossQuestionFromContext(context);
    if (pendingBossQuestion !== undefined) {
      payload.pendingBossQuestion = pendingBossQuestion;
    }
  }
  if (to === 'failed') {
    const lastError = normalizeErrorFull(context.lastError);
    if (lastError !== undefined) {
      payload.lastError = lastError;
    }
  }
  return payload;
}

// Internal export surface for tests. Not part of the stable public API;
// the leading underscore signals "subject to change." Each member is
// referenced here so `noUnusedLocals` stays clean while later tasks
// wire the factory body to use them.
export const _internal = {
  composePlayerPrompt,
  resolvePlayerId,
  adjudicate,
  classifyBossText,
  captainBridge,
  STATE_LABELS,
  stateMetadata,
  pendingBossQuestionFromContext,
  formatAwaitBossReplyQuestion,
  formatAwaitBossReplyMarker,
  formatStateEntry,
  formatTransition,
  formatClassification,
  stateTelemetryPayload,
  normalizeErrorCompact,
  normalizeErrorFull,
  normalizeEventForTelemetry,
  VERBATIM_PAYLOAD_FIELDS,
};

type TraceType = PlaybookTraceEvent['type'];
type BossSettlementOutcome =
  | 'no-action'
  | 'quiescent'
  | 'failed'
  | 'terminal'
  | 'aborted';

interface TracePosition {
  turnId?: number;
  callId?: string;
}

export default function createPlaybookRuntime(
  options: CodePlaybookOptions,
): PlaybookRuntime {
  let actor: ReturnType<typeof createActor> | undefined;
  let session: PlaybookSession | undefined;
  let initialized = false;
  let initInFlight: Promise<void> | undefined;
  let savedPorts: PlaybookPorts | undefined;
  let runtimePorts: PlaybookPorts | undefined;
  // The Boss's per-turn AbortSignal, surfaced to captainBridge so
  // ports.callPlayer / callJudge see the right cancellation source.
  // null between turns; set by handleBossInput.
  let activeSignal: AbortSignal | undefined;
  let activeTurnId: number | undefined;
  // Previous root-machine state for the inspect-driven telemetry /
  // status emitter. undefined before the first inspect firing.
  let priorState: unknown;

  let traceSequence = 0;
  let turnSequence = 0;
  let judgeCallSequence = 0;
  let playerCallSequence = 0;
  const playerResumeTokens = new Map<string, string>();

  // Emission queue. slc/link.md says emissions "shall be ordered,
  // awaited, and never-dropped"; subscribe/inspect callbacks are
  // synchronous and can't await, so each emit is enqueued and a
  // single drainer processes them sequentially.
  let emissionTail: Promise<void> = Promise.resolve();
  let emissionFailure: unknown;

  function enqueueEmit(fn: () => Promise<void>): void {
    emissionTail = emissionTail.then(async () => {
      try {
        await fn();
      } catch (error) {
        emissionFailure ??= error;
      }
    });
  }

  async function drainEmissions(): Promise<void> {
    while (true) {
      const tail = emissionTail;
      await tail;
      if (tail === emissionTail) break;
    }
    if (emissionFailure !== undefined) {
      const error = emissionFailure;
      emissionFailure = undefined;
      throw error;
    }
  }

  function requireSession(): PlaybookSession {
    if (!session) {
      throw new Error('createPlaybookRuntime: init must be called first');
    }
    return session;
  }

  function requireHostPorts(): PlaybookPorts {
    if (!savedPorts) {
      throw new Error('createPlaybookRuntime: init must be called first');
    }
    return savedPorts;
  }

  async function emitTrace(
    type: TraceType,
    payload: unknown,
    position: TracePosition = {},
  ): Promise<void> {
    const currentSession = requireSession();
    const event: PlaybookTraceEvent = {
      schemaVersion: 1,
      sessionId: currentSession.sessionId,
      playbookId: currentSession.playbookId,
      sequence: ++traceSequence,
      timestamp: Date.now(),
      type,
      ...(position.turnId !== undefined
        ? { turnId: position.turnId }
        : {}),
      ...(position.callId !== undefined
        ? { callId: position.callId }
        : {}),
      payload,
    };
    await currentSession.ports.emitTelemetry({
      topic: 'playbook.trace',
      payload: event,
    });
  }

  function stateIdentity(stateId: string | undefined): { stateId?: string } {
    return stateId === undefined ? {} : { stateId };
  }

  function createRuntimePorts(hostPorts: PlaybookPorts): PlaybookPorts {
    return {
      callPlayer: (playerId, prompt, signal, callOptions) =>
        hostPorts.callPlayer(playerId, prompt, signal, callOptions),
      callJudge: (prompt, signal) => hostPorts.callJudge(prompt, signal),
      emitStatus: async (message, data) => {
        await emitTrace(
          'status.emitted',
          {
            message,
            ...(data !== undefined ? { data } : {}),
          },
          activeTurnId !== undefined ? { turnId: activeTurnId } : {},
        );
        await hostPorts.emitStatus(message, data);
      },
      emitTelemetry: (event) => hostPorts.emitTelemetry(event),
    };
  }

  const boundary: RuntimeBoundaryCalls = {
    async callPlayer(input, playerId, prompt, signal): Promise<PlayerResult> {
      // State-entry telemetry/status must precede the call they describe.
      await drainEmissions();
      const turnId = activeTurnId;
      const callId = `player-${++playerCallSequence}`;
      const stateId = stateIdBySourceItem.get(input.sourceItem);
      const resume = playerResumeTokens.get(playerId) ?? false;
      const identity = {
        purpose: 'captain' as const,
        ...stateIdentity(stateId),
        sourceItem: input.sourceItem,
        playerId,
        resume,
      };

      await emitTrace(
        'player.call.started',
        { ...identity, prompt },
        {
          ...(turnId !== undefined ? { turnId } : {}),
          callId,
        },
      );

      let result: PlayerResult;
      try {
        result = await requireHostPorts().callPlayer(
          playerId,
          prompt,
          signal,
          { resume },
        );
      } catch (error) {
        await emitTrace(
          'player.call.finished',
          {
            ...identity,
            status: signal.aborted ? 'aborted' : 'error',
            error: normalizeErrorFull(error),
          },
          {
            ...(turnId !== undefined ? { turnId } : {}),
            callId,
          },
        );
        // A thrown port call carries no authoritative result, so the
        // prior token remains available for a later explicit resume.
        throw error;
      }

      if (
        typeof result.resumeToken === 'string' &&
        result.resumeToken.trim().length > 0
      ) {
        playerResumeTokens.set(playerId, result.resumeToken);
      } else {
        playerResumeTokens.delete(playerId);
      }

      await emitTrace(
        'player.call.finished',
        {
          ...identity,
          status: result.status,
          ...(result.finalText !== undefined
            ? { finalText: result.finalText }
            : {}),
          ...(result.error !== undefined
            ? { error: normalizeErrorFull(result.error) }
            : {}),
          ...(result.resumeToken !== undefined
            ? { resumeToken: result.resumeToken }
            : {}),
        },
        {
          ...(turnId !== undefined ? { turnId } : {}),
          callId,
        },
      );
      return result;
    },

    async callJudge(purpose, stateId, prompt, signal): Promise<string> {
      // A transition/status queued synchronously by XState must reach the
      // host before the judge call that follows it.
      await drainEmissions();
      const turnId = activeTurnId;
      const callId = `judge-${++judgeCallSequence}`;
      const identity = { purpose, ...stateIdentity(stateId) };

      await emitTrace(
        'judge.call.started',
        { ...identity, prompt },
        {
          ...(turnId !== undefined ? { turnId } : {}),
          callId,
        },
      );
      try {
        const reply = await requireHostPorts().callJudge(prompt, signal);
        await emitTrace(
          'judge.call.finished',
          { ...identity, status: 'ok', reply },
          {
            ...(turnId !== undefined ? { turnId } : {}),
            callId,
          },
        );
        return reply;
      } catch (error) {
        await emitTrace(
          'judge.call.finished',
          {
            ...identity,
            status: signal.aborted ? 'aborted' : 'error',
            error: normalizeErrorFull(error),
          },
          {
            ...(turnId !== undefined ? { turnId } : {}),
            callId,
          },
        );
        throw error;
      }
    },
  };

  function tracePositionForActiveTurn(): TracePosition {
    return activeTurnId === undefined ? {} : { turnId: activeTurnId };
  }

  function buildActor(
    ports: PlaybookPorts,
  ): ReturnType<typeof createActor> {
    priorState = undefined;
    return createActor(
      codingMachine.provide({
        actors: {
          captain: captainBridge(ports, () => activeSignal, boundary),
        },
      }),
      {
        input: options,
        inspect: (inspectionEvent) => {
          if (inspectionEvent.type !== '@xstate.snapshot') return;
          const snap = inspectionEvent.snapshot as {
            value?: unknown;
            context?: Record<string, unknown>;
          };
          // Filter out captain sub-actor (fromPromise) snapshots —
          // only the root codingMachine snapshot has a string value.
          if (typeof snap.value !== 'string') return;
          const to = snap.value;
          const from = priorState;
          priorState = to;
          // Telemetry on every transition (PBRT-14).
          const context = snap.context ?? {};
          const payload = stateTelemetryPayload(
            from,
            to,
            inspectionEvent.event,
            context,
          );
          const tracePosition = tracePositionForActiveTurn();
          enqueueEmit(async () => {
            await emitTrace('fsm.transition', payload, tracePosition);
            await ports.emitTelemetry({
              topic: 'playbook.fsm.state',
              payload,
            });
          });
          // Captain pane (PBRT-3 / PBRT-14): show the transition
          // guard first (when this is an actor-done transition with
          // a known guard), then the new state entry, then any
          // context riders the entering state cares about. Terminal
          // entry to `failed` carries `lastError` as the data arg.
          if (!CAPTAIN_PANE_STATES.has(to)) return;
          const transitionLine = formatTransition(inspectionEvent.event);
          if (transitionLine !== undefined) {
            enqueueEmit(() => ports.emitStatus(transitionLine));
          }
          // awaitBossReply surfaces two lines per PBRT-3 / PBRT-14: the
          // full player question as captain speech, then the rider-less
          // routing marker. The full-question telemetry rides
          // stateTelemetryPayload above.
          if (to === 'awaitBossReply') {
            const questionLine = formatAwaitBossReplyQuestion(context);
            const markerLine = formatAwaitBossReplyMarker(context);
            enqueueEmit(() => ports.emitStatus(questionLine));
            enqueueEmit(() => ports.emitStatus(markerLine));
            return;
          }
          const entryLine = formatStateEntry(to);
          if (entryLine === undefined) return;
          if (to === 'failed') {
            const lastError = (snap.context as { lastError?: unknown })
              ?.lastError;
            const normalized = normalizeErrorCompact(lastError);
            enqueueEmit(() =>
              ports.emitStatus(
                entryLine,
                normalized === undefined
                  ? undefined
                  : { lastError: normalized },
              ),
            );
          } else {
            enqueueEmit(() => ports.emitStatus(entryLine));
          }
        },
      },
    );
  }

  const runtime = {
    async init(nextSession: PlaybookSession): Promise<void> {
      if (initialized) {
        throw new Error('createPlaybookRuntime.init: already initialized');
      }
      if (
        typeof nextSession.sessionId !== 'string' ||
        nextSession.sessionId.trim().length === 0
      ) {
        throw new Error(
          'createPlaybookRuntime.init: sessionId must be a non-empty string',
        );
      }
      if (
        typeof nextSession.playbookId !== 'string' ||
        nextSession.playbookId.trim().length === 0
      ) {
        throw new Error(
          'createPlaybookRuntime.init: playbookId must be a non-empty string',
        );
      }
      initialized = true;
      const initTask = (async () => {
        // Copy the identity fields so later caller mutation cannot change the
        // session bound to trace events.
        session = {
          sessionId: nextSession.sessionId,
          playbookId: nextSession.playbookId,
          ports: nextSession.ports,
        };
        savedPorts = nextSession.ports;
        runtimePorts = createRuntimePorts(nextSession.ports);
        await emitTrace('session.started', { stateId: 'ready' });
        actor = buildActor(runtimePorts);
        actor.start();
        await drainEmissions();
      })();
      initInFlight = initTask;
      try {
        await initTask;
      } finally {
        if (initInFlight === initTask) initInFlight = undefined;
      }
    },

    async handleBossInput({
      text,
      signal,
    }: {
      text: string;
      signal: AbortSignal;
    }): Promise<void> {
      if (!actor || !savedPorts) {
        throw new Error(
          'createPlaybookRuntime.handleBossInput: init must be called first',
        );
      }
      const turnId = ++turnSequence;
      activeTurnId = turnId;
      activeSignal = signal;
      let outcome: BossSettlementOutcome = 'no-action';
      let settlementError: unknown;
      try {
        await emitTrace(
          'boss.input.received',
          { text },
          { turnId },
        );
        // 1. Classify non-empty text into an FSM event through the judge.
        const event = await classifyBossText(
          text,
          runtimePorts!,
          signal,
          actor.getSnapshot(),
          boundary,
        );
        // Empty input, no-action classifier output, or invalid classifier
        // output — nothing to send.
        if (event === undefined) {
          await drainEmissions();
          return;
        }
        // 2. Captain-pane classification line (PBRT-14): the bare
        //    FSM event type, emitted before the FSM advances so the
        //    host can render it as captain speech (e.g.,
        //    `captain> START_CODING`). Enqueued so it interleaves
        //    cleanly with the inspect-driven transition emissions.
        const echoPorts = runtimePorts!;
        enqueueEmit(() =>
          echoPorts.emitStatus(formatClassification(event.type)),
        );
        // 3. final state ('done') cannot accept new events — dispose
        //    and reconstruct per DR-004 §5.
        if (actor.getSnapshot().status === 'done') {
          actor.stop();
          actor = buildActor(runtimePorts!);
          actor.start();
        }
        // 4. Send the event.
        actor.send(event);
        // 5. Drive to quiescence. On signal-abort we take no FSM
        //    action: the captain bridge's awaited callPlayer rejects
        //    naturally, the bridge throws, XState routes through
        //    onError → #failed, and this loop sees the quiescent
        //    snapshot and returns (DR-004 §8 natural rejection).
        await driveToQuiescence(actor);
        // Drain transition emissions before returning so the Boss
        // sees the final status line for this turn.
        await drainEmissions();
        const stateId = actor.getSnapshot().value;
        outcome = signal.aborted
          ? 'aborted'
          : stateId === 'failed'
            ? 'failed'
            : actor.getSnapshot().status === 'done' || stateId === 'done'
              ? 'terminal'
              : 'quiescent';
      } catch (error) {
        settlementError = error;
        outcome = signal.aborted ? 'aborted' : 'failed';
        throw error;
      } finally {
        try {
          await drainEmissions();
          const stateId = actor?.getSnapshot().value;
          await emitTrace(
            'boss.input.settled',
            {
              outcome,
              ...(typeof stateId === 'string' ? { stateId } : {}),
              ...(settlementError !== undefined
                ? { error: normalizeErrorFull(settlementError) }
                : {}),
            },
            { turnId },
          );
        } finally {
          activeSignal = undefined;
          activeTurnId = undefined;
        }
      }
    },

    async dispose(): Promise<void> {
      if (initInFlight !== undefined) {
        try {
          await initInFlight;
        } catch {
          // Dispose still releases whatever an unsuccessful init bound.
        }
      }
      const stateId = actor?.getSnapshot().value;
      if (actor) {
        actor.stop();
        actor = undefined;
      }
      // Drain any in-flight emissions per slc/link.md §Session
      // lifecycle ("stop the actor and drain pending port emissions").
      const failures: unknown[] = [];
      try {
        await drainEmissions();
      } catch (error) {
        failures.push(error);
      }
      if (session !== undefined) {
        try {
          await emitTrace('session.disposed', {
            ...(typeof stateId === 'string' ? { stateId } : {}),
          });
        } catch (error) {
          failures.push(error);
        }
      }
      playerResumeTokens.clear();
      savedPorts = undefined;
      runtimePorts = undefined;
      session = undefined;
      if (failures.length === 1) throw failures[0];
      if (failures.length > 1) {
        throw new AggregateError(failures, 'playbook runtime disposal failed');
      }
    },

    // @internal — test-only escape hatch for inspecting the
    // underlying actor's snapshot. Most state assertions are now
    // expressible via the recorded emitStatus / emitTelemetry
    // calls (DR-004 §9); the hatch stays for the few cases where
    // direct context inspection is clearer (e.g., the dispose
    // teardown test).
    _getActor() {
      return actor;
    },
  };
  return runtime as PlaybookRuntime;
}

function driveToQuiescence(
  actor: ReturnType<typeof createActor>,
): Promise<void> {
  return new Promise<void>((resolve) => {
    if (isQuiescent(actor.getSnapshot())) {
      resolve();
      return;
    }
    const sub = actor.subscribe((snap) => {
      if (isQuiescent(snap)) {
        sub.unsubscribe();
        resolve();
      }
    });
  });
}

function isQuiescent(snap: { value: unknown }): boolean {
  const v = snap.value;
  return typeof v === 'string' && QUIESCENT_STATES.has(v);
}
